import sys
from collections import deque

s = sys.stdin.readline().strip()
n = len(s)
if n <= 9:
    seen = {s: 0}
    q = deque([s])
    ans = None
    while q:
        u = q.popleft()
        if u == u[::-1]:
            ans = seen[u]
            break
        for i in range(n - 1):
            v = u[:i] + u[i + 1] + u[i] + u[i + 2:]
            if v not in seen:
                seen[v] = seen[u] + 1
                q.append(v)
    print(ans)
else:
    t = list(s)
    res = 0
    while len(t) > 1:
        j = len(t) - 1 - t[::-1].index(t[0])
        if j == 0:
            t[0], t[1] = t[1], t[0]
            res += 1
        else:
            res += len(t) - 1 - j
            t.pop(j)
            t.pop(0)
    print(res)

