def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def pal(n, k):
        half = [rng.choice(letters[:k]) for _ in range(n // 2)]
        mid = [rng.choice(letters[:k])] if n % 2 else []
        return half + mid + half[::-1]
    def shuffled(n, k):
        t = pal(n, k)
        rng.shuffle(t)
        return ''.join(t)
    tests = ['a', 'aa', 'ab' if False else 'aba', 'baa', 'aab', 'abab', 'aabb', 'abcba', 'abcab', 'aabcb', 'level', 'zzzzzzzz']
    for n in range(2, 9):
        for _ in range(3):
            tests.append(shuffled(n, rng.randint(1, 4)))
    for n in (500, 777, 1001):
        tests.append(shuffled(n, rng.randint(2, 26)))
    tests.append('a' * 1000 + 'b' * 1000)
    tests.append(''.join(sorted(shuffled(2000, 26))))
    tests.append(''.join(sorted(shuffled(1999, 5))))
    tests.append(shuffled(2000, 2))
    tests.append(shuffled(2000, 26))
    tests.append('ab' * 1000)
    return tests

